import React, { useState, useEffect } from "react";
import { useParams, useNavigate, useSearchParams } from "react-router-dom";
import axios from "axios";
import { InputText } from "primereact/inputtext";
import { Dropdown } from "primereact/dropdown";
import { Calendar } from "primereact/calendar";
import { Button } from "primereact/button";
import "primereact/resources/themes/lara-light-blue/theme.css";
import "primereact/resources/primereact.min.css";
import "../components/css/petshop.css";

function PetShop() {
  const [searchParams] = useSearchParams();
  const clinicId = searchParams.get("id");
  const ownerId = searchParams.get("ownerId");
  const isGuest = searchParams.get("guest");
  const [step, setStep] = useState(1);
  const [selectedDate, setSelectedDate] = useState("");
  const [firstname, setFirstName] = useState("");
  const [lastname, setLastName] = useState("");
  const [email, setEmail] = useState("");
  const [petName, setPetName] = useState("");
  const [petType, setPetType] = useState("");
  const [petBreed, setPetBreed] = useState("");
  const [petAge, setPetAge] = useState("");
  const [petGender, setPetGender] = useState("");
  const [services, setServices] = useState([]);
  const [pets, setPets] = useState([]);
  const [selectedService, setSelectedService] = useState("");
  const [clinic, setClinic] = useState(null);
  const [otp, setOtp] = useState("");
  const [otpSent, setOtpSent] = useState(false);
  const navigate = useNavigate();

  useEffect(() => {
    const fetchClinicData = async () => {
      if (!clinicId) {
        console.error("Clinic ID is undefined");
        return;
      }
      try {
        const clinicResponse = await axios.get(`http://localhost:5000/api/clinics/${clinicId}`);
        setClinic(clinicResponse.data);

        const servicesResponse = await axios.get(`http://localhost:5000/api/services/clinic/${clinicId}`);
        setServices(servicesResponse.data);
      } catch (error) {
        console.error("Error fetching clinic or services:", error);
      }
    };

    const fetchOwnerData = async () => {
      if (ownerId && !isGuest) {
        try {
          const token = localStorage.getItem("token");
          if (token) {
            const ownerResponse = await axios.get(`http://localhost:5000/api/owners/${ownerId}`, {
              headers: { "Authorization": `Bearer ${token}` }
            });
            setFirstName(`${ownerResponse.data.firstname}`);
            setLastName (`${ownerResponse.data.lastname}`);
            setEmail(ownerResponse.data.email);

            const fetchPets = async () => {
              try {
                const response = await fetch(`http://localhost:5000/api/pets`, {
                  method: "GET",
                  headers: {
                    "Authorization": `Bearer ${token}`,
                    "Content-Type": "application/json",
                  },
                });

                if (!response.ok) {
                  throw new Error("Failed to fetch pets");
                }

                const data = await response.json();
                const ownerPets = data.filter((p) => p.owner_id === ownerId);
                setPets(ownerPets);
              } catch (error) {
                console.error("Error fetching pets:", error);
              }
            };

            fetchPets();
          }
        } catch (error) {
          console.error("Error fetching owner or pets:", error);
        }
      }
    };

    fetchClinicData();
    fetchOwnerData();
  }, [clinicId, ownerId, isGuest]);

  const handleSubmit = async () => {
    if (!selectedDate || !petName || !petType || !email) {
      alert("Please fill out all required fields!");
      return;
    }

    try {
      const appointmentData = {
        owner_id: ownerId,
        firstName: isGuest ? firstname : undefined, // Only include for guests
        lastName: isGuest ? lastname : undefined,   // Only include for guests
        email: isGuest ? email : undefined,         // Only include for guests
        petName,
        petType,
        clinic_id: clinicId,
        date: selectedDate,
        service_id: selectedService,
        vet_id: "someVetId", // Replace with actual vet ID if needed
        notes: "Some notes",
      };

      if (isGuest) {
        // If it's a guest appointment, send the data to the backend to handle OTP and registration
        const response = await axios.post("http://localhost:5000/api/appointments/book", appointmentData);
        alert(response.data.message);
        setOtpSent(true);
        setStep(4); // Move to OTP verification step
      } else {
        // If it's a registered owner, create the appointment directly
        const response = await axios.post("http://localhost:5000/api/appointments/book", appointmentData);
        alert("Appointment booked successfully!");
        navigate(`/appointments`);
      }
    } catch (error) {
      console.error("Error creating appointment:", error);
      alert("An error occurred while booking the appointment.");
    }
  };

  const handleVerifyOTP = async () => {
    try {
      const response = await axios.post("http://localhost:5000/api/appointments/verify-otp", {
        email,
        otp,
      });

      alert(response.data.message);
      navigate(`/appointments`);
    } catch (error) {
      console.error("Error verifying OTP:", error);
      alert("Invalid or expired OTP.");
    }
  };
  
  return (
    <div className="form-container">
      {step === 1 && (
        <Button label="Start Booking" onClick={() => setStep(2)} />
      )}

      {step === 2 && (
        <div>
          <h3>Appointment Details</h3>
          <label>SCHEDULED ON</label>
          <Calendar value={selectedDate} onChange={(e) => setSelectedDate(e.value)} required showIcon />
          
          <label>SERVICE</label>
          <Dropdown value={selectedService} options={services} onChange={(e) => setSelectedService(e.value)} required />

          <Button label="Next" onClick={() => setStep(3)} />
        </div>
      )}

      {step === 3 && (
        <div>
          <h3>Pet & Owner Details</h3>
          <label>First Name</label>
          <InputText value={firstname} onChange={(e) => setFirstName(e.target.value)} required />

          <label>Last Name</label>
          <InputText value={lastname} onChange={(e) => setLastName(e.target.value)} required />

          <label>Email</label>
          <InputText value={email} onChange={(e) => setEmail(e.target.value)} required />

          <label>Pet Name</label>
          <InputText value={petName} onChange={(e) => setPetName(e.target.value)} required />

          <label>Pet Type</label>
          <InputText value={petType} onChange={(e) => setPetType(e.target.value)} required />

          <label>Pet Breed</label>
          <InputText value={petBreed} onChange={(e) => setPetBreed(e.target.value)} />

          <label>Pet Age</label>
          <InputText value={petAge} onChange={(e) => setPetAge(e.target.value)} keyfilter="int" />

          <label>Pet Gender</label>
          <Dropdown value={petGender} options={[{ label: "Male", value: "Male" }, { label: "Female", value: "Female" }]} onChange={(e) => setPetGender(e.value)} required />

          <Button label="Submit" onClick={handleSubmit} />
        </div>
      )}
    </div>
  );
}

export default PetShop;
